from __future__ import annotations

from consent_models import ConsentEvent, ContactConsentRecord
from merge_policy import MergeDecision


def build_audit_event(
    event: ConsentEvent,
    decision: MergeDecision,
    record: ContactConsentRecord,
) -> dict[str, object]:
    """Create one audit row describing how a consent event was resolved.

    Compliance reviewers read these rows to reconstruct why a contact ended up
    subscribed or unsubscribed on a given channel.
    """

    return {
        "contact_id": event.contact_id,
        "channel": event.channel,
        "event_id": event.event_id,
        "incoming_action": event.action,
        "incoming_source": event.source,
        "effective_at": event.effective_at.isoformat(),
        "received_seq": event.received_seq,
        "resolved_action": decision.winner.action,
        "resolved_source": decision.winner.source,
        "changed": decision.changed,
        "reason": decision.reason,
        "channel_snapshot": record.snapshot().get(event.channel, "unknown"),
    }


class ConsentAuditTrail:
    """Append-only log of consent merge decisions."""

    def __init__(self) -> None:
        self._events: list[dict[str, object]] = []

    def add(self, event: dict[str, object]) -> None:
        self._events.append(event)

    def all_events(self) -> list[dict[str, object]]:
        return list(self._events)

    def count(self) -> int:
        return len(self._events)

    def for_contact(self, contact_id: str) -> list[dict[str, object]]:
        return [event for event in self._events if event.get("contact_id") == contact_id]

    def for_channel(self, contact_id: str, channel: str) -> list[dict[str, object]]:
        return [
            event
            for event in self._events
            if event.get("contact_id") == contact_id and event.get("channel") == channel
        ]

    def changes_only(self) -> list[dict[str, object]]:
        return [event for event in self._events if event.get("changed")]

    def reactivations(self) -> list[dict[str, object]]:
        """Audit rows where a channel moved from opted-out to opted-in."""

        flips: list[dict[str, object]] = []
        for event in self._events:
            if not event.get("changed"):
                continue
            if event.get("incoming_action") == "opt_in" and event.get("resolved_action") == "opt_in":
                flips.append(event)
        return flips

    def last_for_channel(self, contact_id: str, channel: str) -> dict[str, object] | None:
        rows = self.for_channel(contact_id, channel)
        if not rows:
            return None
        return rows[-1]

