from __future__ import annotations

from dataclasses import dataclass

from consent_models import CHANNELS


@dataclass(frozen=True)
class ChannelDefinition:
    """Static metadata about a messaging channel.

    `requires_double_opt_in` flags channels where regulators expect an explicit
    confirmation step. It does not change merge resolution; it is metadata the
    downstream send service reads.
    """

    name: str
    display_name: str
    requires_double_opt_in: bool
    default_subscribed: bool = False


DEFAULT_DEFINITIONS = (
    ChannelDefinition("email", "Email", requires_double_opt_in=False),
    ChannelDefinition("sms", "SMS / Text", requires_double_opt_in=True),
    ChannelDefinition("push", "Mobile Push", requires_double_opt_in=False),
)


class ChannelRegistry:
    """Lookup table for channel metadata used by the coordinator and reports."""

    def __init__(self, definitions: tuple[ChannelDefinition, ...] | None = None) -> None:
        defs = definitions or DEFAULT_DEFINITIONS
        self._by_name = {definition.name: definition for definition in defs}
        for channel in CHANNELS:
            if channel not in self._by_name:
                self._by_name[channel] = ChannelDefinition(
                    name=channel,
                    display_name=channel.upper(),
                    requires_double_opt_in=False,
                )

    def get(self, channel: str) -> ChannelDefinition:
        if channel not in self._by_name:
            raise ValueError(f"unsupported channel: {channel}")
        return self._by_name[channel]

    def is_known(self, channel: str) -> bool:
        return channel in self._by_name

    def display_name(self, channel: str) -> str:
        return self.get(channel).display_name

    def requires_double_opt_in(self, channel: str) -> bool:
        return self.get(channel).requires_double_opt_in

    def all_channels(self) -> list[str]:
        return [channel for channel in CHANNELS if channel in self._by_name]

    def default_subscribed(self, channel: str) -> bool:
        return self.get(channel).default_subscribed

    def summary(self) -> list[dict[str, object]]:
        rows: list[dict[str, object]] = []
        for channel in self.all_channels():
            definition = self._by_name[channel]
            rows.append(
                {
                    "channel": definition.name,
                    "display_name": definition.display_name,
                    "requires_double_opt_in": definition.requires_double_opt_in,
                    "default_subscribed": definition.default_subscribed,
                }
            )
        return rows

