from __future__ import annotations

from datetime import datetime, timedelta, timezone


# Small helpers for reasoning about consent event timing. Upstream systems
# stamp events in their own clocks, so the pipeline normalizes everything to
# UTC and compares from there.


def to_utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def is_strictly_after(left: datetime, right: datetime) -> bool:
    return to_utc(left) > to_utc(right)


def is_strictly_before(left: datetime, right: datetime) -> bool:
    return to_utc(left) < to_utc(right)


def is_same_instant(left: datetime, right: datetime) -> bool:
    return to_utc(left) == to_utc(right)


def seconds_between(earlier: datetime, later: datetime) -> float:
    delta = to_utc(later) - to_utc(earlier)
    return delta.total_seconds()


def within_window(candidate: datetime, anchor: datetime, window_seconds: int) -> bool:
    """True when `candidate` is within `window_seconds` of `anchor` in either
    direction. Used to flag near-simultaneous consent changes for review.
    """

    if window_seconds < 0:
        raise ValueError("window_seconds must be non-negative")
    low = to_utc(anchor) - timedelta(seconds=window_seconds)
    high = to_utc(anchor) + timedelta(seconds=window_seconds)
    moment = to_utc(candidate)
    return low <= moment <= high


def newest(timestamps: list[datetime]) -> datetime | None:
    if not timestamps:
        return None
    return max(to_utc(value) for value in timestamps)


def oldest(timestamps: list[datetime]) -> datetime | None:
    if not timestamps:
        return None
    return min(to_utc(value) for value in timestamps)


def order_by_effective(events: list) -> list:
    """Stable sort of objects exposing an `effective_at` attribute, oldest
    first. Ties keep their original relative order.
    """

    return sorted(events, key=lambda item: to_utc(item.effective_at))

