from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone


# Channels are tracked independently. An email opt-out must never silently
# change SMS or push consent, and vice versa.
CHANNELS = ("email", "sms", "push")

# A consent event either grants permission (opt_in) or withdraws it (opt_out).
CONSENT_ACTIONS = ("opt_in", "opt_out")

# Systems that publish consent changes into the sync pipeline.
SOURCE_SYSTEMS = ("crm", "data_cloud", "marketing_cloud", "preference_center")

# When a contact has never been seen on a channel, this is the assumed state.
DEFAULT_STATE = "unknown"


def _require_text(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} required")


def _coerce_timestamp(value: datetime) -> datetime:
    if not isinstance(value, datetime):
        raise ValueError("effective_at must be a datetime")
    if value.tzinfo is None:
        # Treat naive timestamps as UTC; upstream systems are inconsistent.
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


@dataclass(frozen=True)
class ConsentEvent:
    """A single consent change for one contact on one channel.

    `effective_at` is when the customer actually made the choice (for example
    when they clicked unsubscribe), which is not the same as when the event
    was delivered to us. `received_seq` is a monotonically increasing number
    assigned at ingestion time, used only for tie-breaking and tracing.
    """

    contact_id: str
    channel: str
    action: str
    source: str
    effective_at: datetime
    received_seq: int
    event_id: str
    reason: str = ""

    def __post_init__(self) -> None:
        _require_text(self.contact_id, "contact_id")
        _require_text(self.event_id, "event_id")
        if self.channel not in CHANNELS:
            raise ValueError(f"unsupported channel: {self.channel}")
        if self.action not in CONSENT_ACTIONS:
            raise ValueError(f"unsupported action: {self.action}")
        if self.source not in SOURCE_SYSTEMS:
            raise ValueError(f"unsupported source: {self.source}")
        if self.received_seq < 0:
            raise ValueError("received_seq must be non-negative")
        object.__setattr__(self, "effective_at", _coerce_timestamp(self.effective_at))

    @property
    def is_opt_out(self) -> bool:
        return self.action == "opt_out"

    @property
    def is_opt_in(self) -> bool:
        return self.action == "opt_in"


@dataclass(frozen=True)
class ChannelConsentState:
    """The resolved consent state for one channel of one contact.

    This is the durable record the rest of the platform reads. Marketing Cloud
    will only send a message on a channel when `subscribed` is True.
    """

    channel: str
    action: str
    source: str
    effective_at: datetime
    event_id: str
    last_seq: int

    def __post_init__(self) -> None:
        if self.channel not in CHANNELS:
            raise ValueError(f"unsupported channel: {self.channel}")
        if self.action not in CONSENT_ACTIONS:
            raise ValueError(f"unsupported action: {self.action}")
        if self.source not in SOURCE_SYSTEMS:
            raise ValueError(f"unsupported source: {self.source}")
        _require_text(self.event_id, "event_id")
        object.__setattr__(self, "effective_at", _coerce_timestamp(self.effective_at))

    @property
    def subscribed(self) -> bool:
        return self.action == "opt_in"

    def from_event(self, event: ConsentEvent) -> "ChannelConsentState":
        return ChannelConsentState(
            channel=event.channel,
            action=event.action,
            source=event.source,
            effective_at=event.effective_at,
            event_id=event.event_id,
            last_seq=event.received_seq,
        )


def state_from_event(event: ConsentEvent) -> ChannelConsentState:
    return ChannelConsentState(
        channel=event.channel,
        action=event.action,
        source=event.source,
        effective_at=event.effective_at,
        event_id=event.event_id,
        last_seq=event.received_seq,
    )


@dataclass
class ContactConsentRecord:
    """All channel consent states for a single contact.

    Channels are stored separately so resolving one channel never reads or
    writes another. Email and SMS consent move independently.
    """

    contact_id: str
    channels: dict[str, ChannelConsentState] = field(default_factory=dict)
    applied_event_ids: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        _require_text(self.contact_id, "contact_id")

    def state_for(self, channel: str) -> ChannelConsentState | None:
        if channel not in CHANNELS:
            raise ValueError(f"unsupported channel: {channel}")
        return self.channels.get(channel)

    def is_subscribed(self, channel: str) -> bool:
        current = self.state_for(channel)
        if current is None:
            return False
        return current.subscribed

    def already_applied(self, event: ConsentEvent) -> bool:
        return event.event_id in self.applied_event_ids

    def set_channel(self, state: ChannelConsentState, event: ConsentEvent) -> None:
        self.channels[state.channel] = state
        self.applied_event_ids.add(event.event_id)

    def mark_seen(self, event: ConsentEvent) -> None:
        self.applied_event_ids.add(event.event_id)

    def snapshot(self) -> dict[str, str]:
        view: dict[str, str] = {}
        for channel in CHANNELS:
            current = self.channels.get(channel)
            view[channel] = current.action if current is not None else DEFAULT_STATE
        return view

