from __future__ import annotations

from consent_models import (
    CHANNELS,
    ChannelConsentState,
    ContactConsentRecord,
)
from merge_policy import MergeDecision


def channel_state_to_dict(state: ChannelConsentState | None) -> dict[str, object] | None:
    if state is None:
        return None
    return {
        "channel": state.channel,
        "action": state.action,
        "subscribed": state.subscribed,
