from __future__ import annotations

from consent_models import CHANNELS, ContactConsentRecord


class ContactConsentStore:
    """In-memory store of resolved consent records, keyed by contact id.

    A real deployment would back this with Data Cloud, but the merge semantics
    are identical: read the current record, resolve, write it back.
    """

    def __init__(self, seed: dict[str, ContactConsentRecord] | None = None) -> None:
        self._by_contact: dict[str, ContactConsentRecord] = dict(seed or {})

    def get(self, contact_id: str) -> ContactConsentRecord | None:
        return self._by_contact.get(contact_id)

    def save(self, record: ContactConsentRecord) -> ContactConsentRecord:
        self._by_contact[record.contact_id] = record
        return record

    def get_or_create(self, contact_id: str) -> ContactConsentRecord:
        record = self._by_contact.get(contact_id)
        if record is None:
            record = ContactConsentRecord(contact_id=contact_id)
            self._by_contact[contact_id] = record
        return record

    def contains(self, contact_id: str) -> bool:
        return contact_id in self._by_contact

    def count(self) -> int:
        return len(self._by_contact)

    def all_records(self) -> list[ContactConsentRecord]:
        return list(self._by_contact.values())

    def contact_ids(self) -> list[str]:
        return sorted(self._by_contact)

    def subscribed_contacts(self, channel: str) -> list[str]:
        if channel not in CHANNELS:
            raise ValueError(f"unsupported channel: {channel}")
        result: list[str] = []
        for contact_id, record in self._by_contact.items():
            if record.is_subscribed(channel):
                result.append(contact_id)
        return sorted(result)

    def channel_breakdown(self, channel: str) -> dict[str, int]:
        counts = {"opt_in": 0, "opt_out": 0, "unknown": 0}
        for record in self._by_contact.values():
            state = record.state_for(channel)
            if state is None:
                counts["unknown"] += 1
            else:
                counts[state.action] += 1
        return counts

    def remove(self, contact_id: str) -> ContactConsentRecord | None:
        return self._by_contact.pop(contact_id, None)

    def snapshot(self) -> dict[str, dict[str, str]]:
        return {contact_id: record.snapshot() for contact_id, record in self._by_contact.items()}

