from __future__ import annotations

from datetime import datetime, timezone

from consent_models import ConsentEvent


# Upstream systems use slightly different field names for the same concept.
# Normalization maps all of them onto the canonical ConsentEvent shape.
ACTION_ALIASES = {
    "opt_in": "opt_in",
    "optin": "opt_in",
    "subscribe": "opt_in",
    "subscribed": "opt_in",
    "resubscribe": "opt_in",
    "opt_out": "opt_out",
    "optout": "opt_out",
    "unsubscribe": "opt_out",
    "unsubscribed": "opt_out",
}

CHANNEL_ALIASES = {
    "email": "email",
    "e-mail": "email",
    "mail": "email",
    "sms": "sms",
    "text": "sms",
    "mobile_sms": "sms",
    "push": "push",
    "mobile_push": "push",
}

SOURCE_ALIASES = {
    "crm": "crm",
    "sales_cloud": "crm",
    "service_cloud": "crm",
    "data_cloud": "data_cloud",
    "cdp": "data_cloud",
    "marketing_cloud": "marketing_cloud",
    "mc": "marketing_cloud",
    "preference_center": "preference_center",
    "prefcenter": "preference_center",
}


def _parse_timestamp(value: object) -> datetime:
    if isinstance(value, datetime):
        if value.tzinfo is None:
            return value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc)
    if isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            return parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    if isinstance(value, (int, float)):
        return datetime.fromtimestamp(float(value), tz=timezone.utc)
    raise ValueError("missing or invalid effective timestamp")


def _normalize_action(value: object) -> str:
    if not isinstance(value, str):
        raise ValueError("action required")
    key = value.strip().lower()
    if key not in ACTION_ALIASES:
        raise ValueError(f"unknown action: {value}")
    return ACTION_ALIASES[key]


def _normalize_channel(value: object) -> str:
    if not isinstance(value, str):
        raise ValueError("channel required")
    key = value.strip().lower()
    if key not in CHANNEL_ALIASES:
        raise ValueError(f"unknown channel: {value}")
    return CHANNEL_ALIASES[key]


def _normalize_source(value: object) -> str:
    if not isinstance(value, str):
        raise ValueError("source required")
    key = value.strip().lower()
    if key not in SOURCE_ALIASES:
        raise ValueError(f"unknown source: {value}")
    return SOURCE_ALIASES[key]


def _pick(raw: dict[str, object], *names: str) -> object:
    for name in names:
        if name in raw and raw[name] is not None:
            return raw[name]
    return None


def normalize_update(raw_update: dict[str, object], received_seq: int) -> ConsentEvent:
    """Translate a raw upstream payload into a canonical ConsentEvent.

    Accepts the common field name variants used by CRM, Data Cloud, Marketing
    Cloud, and the preference center.
    """

    contact_id = _pick(raw_update, "contact_id", "contactId", "subscriber_key", "id")
    if not isinstance(contact_id, str) or not contact_id.strip():
        raise ValueError("contact_id required")

    channel = _normalize_channel(_pick(raw_update, "channel", "subscription_channel"))
    action = _normalize_action(_pick(raw_update, "action", "status", "consent"))
    source = _normalize_source(_pick(raw_update, "source", "system", "origin"))
    effective_raw = _pick(raw_update, "effective_at", "effectiveAt", "timestamp", "occurred_at")
    effective_at = _parse_timestamp(effective_raw)

    event_id = _pick(raw_update, "event_id", "eventId", "id")
    if not isinstance(event_id, str) or not event_id.strip():
        event_id = f"{contact_id}:{channel}:{source}:{received_seq}"

    reason = _pick(raw_update, "reason", "note")
    reason_text = reason if isinstance(reason, str) else ""

    return ConsentEvent(
        contact_id=contact_id.strip(),
        channel=channel,
        action=action,
        source=source,
        effective_at=effective_at,
        received_seq=received_seq,
        event_id=event_id.strip() if isinstance(event_id, str) else str(event_id),
        reason=reason_text,
    )

