from __future__ import annotations

from consent_models import (
    ChannelConsentState,
    ConsentEvent,
    state_from_event,
)


# Source systems carry different levels of trust when two changes describe the
# same moment. The preference center is the customer's own voice, so it ranks
# highest; CRM and Data Cloud are downstream replicas.
SOURCE_TRUST = {
    "preference_center": 4,
    "marketing_cloud": 3,
    "crm": 2,
    "data_cloud": 1,
}


def source_trust(source: str) -> int:
    return SOURCE_TRUST.get(source, 0)


class MergeDecision:
    """Result of comparing an incoming event against the current state."""

    def __init__(self, winner: ChannelConsentState, changed: bool, reason: str) -> None:
        self.winner = winner
        self.changed = changed
        self.reason = reason

    def as_dict(self) -> dict[str, object]:
        return {
            "channel": self.winner.channel,
            "action": self.winner.action,
            "source": self.winner.source,
            "event_id": self.winner.event_id,
            "changed": self.changed,
            "reason": self.reason,
        }


def _newer(left, right) -> bool:
    """True when `left` happened strictly after `right`."""

    return left.effective_at > right.effective_at


def _same_moment(left, right) -> bool:
    return left.effective_at == right.effective_at


def resolve_channel_consent(
    current: ChannelConsentState | None,
    incoming: ConsentEvent,
) -> MergeDecision:
    """Decide the consent state for one channel given the current record and a
    newly arrived event.

    The first event a contact has on a channel always wins by default. After
    that, the more recent consent choice should take effect.
    """

    candidate = state_from_event(incoming)

    if current is None:
        return MergeDecision(candidate, True, "first_event_for_channel")

    # A consent choice that the customer made more recently reflects their
    # current wishes and should replace what we have on file.
    if _newer(candidate, current):
        return MergeDecision(candidate, True, "newer_choice_applied")

    if _same_moment(candidate, current):
        return _resolve_tie(current, candidate)

    # The incoming event is older than what we already stored, so it is a
    # late-arriving replica of a choice that has since been superseded.
    return _apply_late_arrival(current, candidate)


def _resolve_tie(current: ChannelConsentState, candidate: ChannelConsentState) -> MergeDecision:
    """Break a tie when two events share the same effective timestamp.

    With identical timestamps we fall back to which system we trust more, and
    then to arrival order so the result is deterministic.
    """

    current_trust = source_trust(current.source)
    candidate_trust = source_trust(candidate.source)
    if candidate_trust > current_trust:
        return MergeDecision(candidate, True, "tie_resolved_by_source_trust")
    if candidate_trust < current_trust:
        return MergeDecision(current, False, "tie_kept_higher_trust_source")
    if candidate.last_seq > current.last_seq:
        return MergeDecision(candidate, True, "tie_resolved_by_arrival")
    return MergeDecision(current, False, "tie_kept_existing")


def _apply_late_arrival(
    current: ChannelConsentState,
    candidate: ChannelConsentState,
) -> MergeDecision:
    """Handle an event whose effective time is older than the stored state."""

    return MergeDecision(current, False, "ignored_older_event")


def merge_event_into_record(
    current: ChannelConsentState | None,
    incoming: ConsentEvent,
) -> MergeDecision:
    """Public entry point used by the coordinator.

    Resolves a single channel and returns the decision, including whether the
    stored state actually changed.
    """

    decision = resolve_channel_consent(current, incoming)
    return decision


def would_reactivate(
    current: ChannelConsentState | None,
    incoming: ConsentEvent,
) -> bool:
    """Helper for diagnostics: would applying `incoming` flip a channel from
    opted-out back to opted-in?
    """

    if current is None:
        return incoming.is_opt_in
    if current.action == "opt_out" and incoming.is_opt_in:
        decision = resolve_channel_consent(current, incoming)
        return decision.winner.action == "opt_in"
    return False


def describe_conflict(
    current: ChannelConsentState | None,
    incoming: ConsentEvent,
) -> dict[str, object]:
    """Build a small explanation used by the audit trail when two consent
    signals disagree.
    """

    if current is None:
        return {
            "channel": incoming.channel,
            "had_prior_state": False,
            "incoming_action": incoming.action,
            "incoming_source": incoming.source,
        }
    return {
        "channel": incoming.channel,
        "had_prior_state": True,
        "current_action": current.action,
        "current_source": current.source,
        "incoming_action": incoming.action,
        "incoming_source": incoming.source,
        "incoming_is_newer": _newer(state_from_event(incoming), current),
        "same_moment": _same_moment(state_from_event(incoming), current),
    }

