from __future__ import annotations

from consent_models import CHANNELS
from consent_serializers import public_consent_summary
from consent_store import ContactConsentStore


def channel_totals(store: ContactConsentStore) -> dict[str, dict[str, int]]:
    """Per-channel counts of opt_in / opt_out / unknown across all contacts."""

    totals: dict[str, dict[str, int]] = {}
    for channel in CHANNELS:
        totals[channel] = store.channel_breakdown(channel)
    return totals


def opted_out_roster(store: ContactConsentStore, channel: str) -> list[str]:
    """Contacts who are currently opted out on a channel.

    The send service must never deliver to these contacts on that channel.
    """

    if channel not in CHANNELS:
        raise ValueError(f"unsupported channel: {channel}")
    roster: list[str] = []
    for record in store.all_records():
        state = record.state_for(channel)
        if state is not None and state.action == "opt_out":
            roster.append(record.contact_id)
    return sorted(roster)


def deliverable_roster(store: ContactConsentStore, channel: str) -> list[str]:
    return store.subscribed_contacts(channel)


def reconciliation_summary(store: ContactConsentStore) -> dict[str, object]:
    contacts = [public_consent_summary(record) for record in store.all_records()]
    return {
        "contact_count": store.count(),
        "channel_totals": channel_totals(store),
        "contacts": sorted(contacts, key=lambda row: row["contact_id"]),
    }


def find_inconsistent_contacts(store: ContactConsentStore) -> list[dict[str, object]]:
    """Surface contacts whose stored source is a downstream replica while a
    higher-trust source exists in their audit history. Reporting only; this
    does not change resolution.
    """

    flagged: list[dict[str, object]] = []
    for record in store.all_records():
        downstream_channels: list[str] = []
        for channel in CHANNELS:
            state = record.state_for(channel)
            if state is None:
                continue
            if state.source in {"crm", "data_cloud"} and state.action == "opt_in":
                downstream_channels.append(channel)
        if downstream_channels:
            flagged.append(
                {
                    "contact_id": record.contact_id,
                    "downstream_opt_in_channels": downstream_channels,
                }
            )
    return flagged


def compare_states(
    before: dict[str, str],
    after: dict[str, str],
) -> dict[str, dict[str, str]]:
    """Diff two channel snapshots and return per-channel transitions."""

    changes: dict[str, dict[str, str]] = {}
    for channel in CHANNELS:
        old = before.get(channel, "unknown")
        new = after.get(channel, "unknown")
        if old != new:
            changes[channel] = {"from": old, "to": new}
    return changes

