from __future__ import annotations

from audit_trail import build_audit_event, ConsentAuditTrail
from channel_registry import ChannelRegistry
from consent_models import (
    CHANNELS,
    ChannelConsentState,
    ConsentEvent,
    ContactConsentRecord,
    state_from_event,
)
from consent_serializers import record_to_dict, decision_to_dict
from consent_store import ContactConsentStore
from event_normalizer import normalize_update
from merge_policy import merge_event_into_record


class ConsentSyncCoordinator:
    """Pulls consent changes from CRM, Data Cloud, Marketing Cloud, and the
    preference center, and keeps a single resolved consent record per contact.

    Each raw update is normalized into a `ConsentEvent`, then merged into the
    contact's record one channel at a time. Channels never affect each other.
    """

    def __init__(
        self,
        store: ContactConsentStore | None = None,
        registry: ChannelRegistry | None = None,
    ) -> None:
        self.store = store or ContactConsentStore()
        self.registry = registry or ChannelRegistry()
        self.audit = ConsentAuditTrail()
        self._seq = 0

    def _next_seq(self) -> int:
        self._seq += 1
        return self._seq

    def _record_for(self, contact_id: str) -> ContactConsentRecord:
        record = self.store.get(contact_id)
        if record is None:
            record = ContactConsentRecord(contact_id=contact_id)
            self.store.save(record)
        return record

    def ingest_update(self, raw_update: dict[str, object]) -> dict[str, object]:
        """Ingest a single raw consent update from an upstream system.

        Returns a result dict describing the merge decision and the resulting
        channel state for the affected channel.
        """

        event = normalize_update(raw_update, self._next_seq())
        return self._apply_event(event)

    def ingest_batch(self, raw_updates: list[dict[str, object]]) -> list[dict[str, object]]:
        """Ingest a batch of raw updates in the order they were delivered.

        Used for reconciliation runs where CRM or Data Cloud replays a window
        of recent changes. Order of delivery is not guaranteed to match the
        order the customer made the choices.
        """

        results: list[dict[str, object]] = []
        ordered = self._order_for_replay(raw_updates)
        for raw_update in ordered:
            event = normalize_update(raw_update, self._next_seq())
            results.append(self._apply_replay_event(event))
        return results

    def _order_for_replay(self, raw_updates: list[dict[str, object]]) -> list[dict[str, object]]:
        # Reconciliation batches are processed in delivery order so that the
        # most recently delivered record settles the channel.
        return list(raw_updates)

    def _apply_event(self, event: ConsentEvent) -> dict[str, object]:
        record = self._record_for(event.contact_id)

        if record.already_applied(event):
            current = record.state_for(event.channel)
            return self._result(event, current, changed=False, reason="duplicate_event_ignored")

        current = record.state_for(event.channel)
        decision = merge_event_into_record(current, event)

        if decision.changed:
            record.set_channel(decision.winner, event)
        else:
            record.mark_seen(event)

        self.store.save(record)
        self.audit.add(build_audit_event(event, decision, record))
        return self._result(event, decision.winner, decision.changed, decision.reason)

    def _apply_replay_event(self, event: ConsentEvent) -> dict[str, object]:
        record = self._record_for(event.contact_id)

        if record.already_applied(event):
            current = record.state_for(event.channel)
            return self._result(event, current, changed=False, reason="duplicate_event_ignored")

        # Reconciliation path: take the delivered record as the new channel
        # state. CRM replays are treated as the settled view for the channel.
        new_state = state_from_event(event)
        record.set_channel(new_state, event)
        self.store.save(record)

        decision = merge_event_into_record(record.state_for(event.channel), event)
        self.audit.add(build_audit_event(event, decision, record))
        return self._result(event, new_state, changed=True, reason="replay_applied")

    def _result(
        self,
        event: ConsentEvent,
        state: ChannelConsentState | None,
        changed: bool,
        reason: str,
    ) -> dict[str, object]:
        return {
            "contact_id": event.contact_id,
            "channel": event.channel,
            "event_id": event.event_id,
            "changed": changed,
            "reason": reason,
            "resolved_action": state.action if state is not None else "unknown",
            "subscribed": bool(state.subscribed) if state is not None else False,
            "resolved_source": state.source if state is not None else None,
        }

    def subscription_state(self, contact_id: str) -> dict[str, str]:
        record = self.store.get(contact_id)
        if record is None:
            return {channel: "unknown" for channel in CHANNELS}
        return record.snapshot()

    def is_subscribed(self, contact_id: str, channel: str) -> bool:
        record = self.store.get(contact_id)
        if record is None:
            return False
        return record.is_subscribed(channel)

    def contact_view(self, contact_id: str) -> dict[str, object] | None:
        record = self.store.get(contact_id)
        if record is None:
            return None
        return record_to_dict(record)

    def audit_events(self) -> list[dict[str, object]]:
        return self.audit.all_events()


def sync_contact_updates(
    raw_updates: list[dict[str, object]],
    contact_id: str | None = None,
) -> dict[str, object]:
    """Convenience entry point: feed a list of raw updates through a fresh
    coordinator and return the final per-channel state for one contact.
    """

    coordinator = ConsentSyncCoordinator()
    results = [coordinator.ingest_update(update) for update in raw_updates]

    target = contact_id
    if target is None and results:
        target = str(results[0]["contact_id"])

    state = coordinator.subscription_state(target) if target else {}
    return {
        "contact_id": target,
        "state": state,
        "results": results,
        "audit_events": coordinator.audit_events(),
    }

